<script setup lang="ts">import{onMounted,ref}from'vue';import{useRoute}from'vue-router';import{request}from'../../api/client';import{ElMessage}from'element-plus';const route=useRoute(),episode=ref<any>(null),episodes=ref<any[]>([]);onMounted(async()=>{try{episodes.value=(await request('/api/v1/dramas/'+route.params.dramaId+'/episodes?user_id=1')).items||[];episode.value=episodes.value.find(x=>String(x.id)===String(route.params.episodeId))}catch{ElMessage.error('剧集加载失败')}})</script>
<template><section class="watch-page"><el-button text @click="$router.back()">← 返回详情</el-button><div class="video-stage"><video v-if="episode?.video_url" :src="episode.video_url" controls autoplay playsinline></video><el-empty v-else description="视频地址未配置"/></div><div class="watch-info"><h1>{{episode?.title||'正在加载...'}}</h1><p>Episode {{episode?.episode_no}}</p></div><el-card><template #header>剧集</template><div class="episode-list"><el-button v-for="e in episodes" :key="e.id" @click="$router.push('/watch/'+route.params.dramaId+'/'+e.id)">{{e.episode_no}}. {{e.title}}</el-button></div></el-card></section></template>